import{_ as n,l as i,o as a,c as l,v as r,p as d,x as t,d as s,i as m,S as T}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"ONNX Runtime","description":"","frontmatter":{"title":"ONNX Runtime","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/onnx-runtime.md","filePath":"llm/onnx-runtime.md","lastUpdated":1789023840000}'),c={name:"llm/onnx-runtime.md"};function N(p,e,P,h,u,O){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="onnx-runtime" tabindex="-1">ONNX Runtime <a class="header-anchor" href="#onnx-runtime" aria-label="Permalink to &quot;ONNX Runtime&quot;">​</a></h1><div class="epigraph"><p>把计算图画成可移植的算子图，运行时按设备选 EP：同一份导出，可以走 CUDA、TensorRT、DirectML 或 CPU，而不把服务绑死在 eager PyTorch。</p><footer>—— ONNX 由 Facebook 与 Microsoft 提出；ONNX Runtime 为 Microsoft 的推理引擎文档与 EP 模型</footer></div><p><a href="/llm/safetensors-format">上一课</a>仍在 PyTorch 权重文件里。本单元「GPU 之外」从可移植运行时开始：ONNX 是算子级 IR，ORT 用 Execution Provider 把图画到硬件。LLM 自回归并不天然适合「导出一次、静态图跑到底」——decode 循环、分页 KV、动态 \\(B\\) 会逼出动态轴与自定义算子。本课写 ORT 能接什么、LLM 上缺口在哪，以免把 BERT 式成功故事抄到生成式服务。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌入模型、重排器、ViT 编码器是静态或半静态图，ORT + TensorRT EP 往往很合适。<a href="/llm/embedding-serving">嵌入服务</a>那课的画像与 ORT 匹配。LLM decode 需要：动态序列、KV 追加、可能的分页、采样核。缺口是导出范围——把整个 generate 循环留在 Python、只把一步 Transformer 导出，还是用 ORT 的 I/O binding 在 C++ 里循环。后者快，但要自己管 KV 缓冲，接近重写引擎。</p><p>自定义算子：Rotary、RMSNorm、分页注意力若未进 ONNX 标准，要登记自定义 op，可移植性立刻下降。这是 ORT 在 LLM 上「看起来通用、实际要绑 EP」的原因。</p><p><span class="marginnote">导出用 <code>torch.onnx.export</code> 或 dynamo 导出，动态轴要声明。漏掉动态 \\(n\\)，就会在 \\(n=512\\) 上编译、在 \\(n=513\\) 上重编译或报错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>适合 ORT 的：编码器、embedding、单步无分页的固定最大长缓冲（给每请求预留 KV，回到碎片问题）。生产级 LLM 服务更多用 vLLM/TRT-LLM；ORT 出现在：Windows DirectML 桌面、CPU、以及与 Azure 工具链绑定的部署。EP 选择：CUDA / TensorRT / DirectML / CPU。TensorRT EP 会再编译引擎，冷启动长，形状桶与<a href="/llm/kernel-autotuning">内核自动调优</a>同类。</p><p>采样仍建议在运行时外做，或用 EP 已有的采样；不要在 ORT 图里塞 Python 回调。</p>',10)),(a(),d(T,null,{default:t(()=>[m(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22PyTorch%20%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20ONNX%5B%22ONNX%20%E5%9B%BE%22%5D%0A%20%20ONNX%20--%3E%20EP%5B%22ORT%20Execution%20Provider%22%5D%0A%20%20EP%20--%3E%20CUDA%5B%22CUDA%20%2F%20TensorRT%22%5D%0A%20%20EP%20--%3E%20DML%5B%22DirectML%22%5D%0A%20%20EP%20--%3E%20CPU%5B%22CPU%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ORT 的价值是 <em>图优化 + EP</em>：常量折叠、算子融合、把子图交给 TensorRT。LLM 的热核若已是 FA，ORT 未必更快；它赢在没有 PyTorch 依赖的桌面/CPU 路径，以及与 ONNX 工具链的运维。会计仍成立：decode 带宽墙不因换成 ORT 而消失。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把「已导出 ONNX」当成完成 LLM 服务。不要在分页 KV 上幻想标准 ONNX 注意力。下一课：Intel 侧的 OpenVINO，画像类似但 EP 换成 Intel 硬件。</p><p>出处：ONNX 规范；ONNX Runtime 文档。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ORT 用 EP 跑 ONNX 图；适合静态/半静态模型。</li><li>LLM decode 要动态 KV 与自定义注意力，超出「导出即服务」。</li><li>动态轴与形状桶决定是否反复编译。</li><li>带宽墙与会计不因运行时更换而失效。</li><li>桌面 DirectML / CPU 是 ORT 的合理主场。</li><li>下一课：OpenVINO。</li><li>出处：ONNX；ONNX Runtime 文档。</li></ul>',7))])}const E=n(c,[["render",N]]);export{_ as __pageData,E as default};
